def get_cart_summary(cart):
    total_items = 0
    total_value = 0
    most_expensive = {"name": "", "price": 0}
    cheapest = {"name": "", "price": 1000}

    for item in cart:
        total_items += item["quantity"]
        item_value = item["price"] * item["quantity"]
        total_value += item_value

        if item["price"] > most_expensive["price"]:
            most_expensive = {"name": item["name"], "price": item["price"]}

        if item["price"] < cheapest["price"]:
            cheapest = {"name": item["name"], "price": item["price"]}

    avg_price = total_value / len(cart)

    summary_data = {
        "total_items": total_items,
        "avg_price": avg_price,
        "most_expensive": most_expensive,
        "cheapest": cheapest
    }

    return summary_data
